(()=>{'use strict';const status=document.querySelector('#offlineStatus'),install=document.querySelector('#installApp');let promptEvent=null;function render(){if(!status)return;status.textContent=navigator.onLine?'📥 주요 안내 화면은 첫 방문 때 기기에 저장됩니다. 최신 경보·안내는 공식 원문을 확인하세요.':'📴 인터넷 연결이 없습니다. 저장된 안내를 표시 중이며 최신 경보·외부 링크는 확인되지 않을 수 있어요.';status.dataset.online=navigator.onLine?'true':'false'}window.addEventListener('online',render);window.addEventListener('offline',render);render();if('serviceWorker'in navigator&&location.protocol==='https:')window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{if(status)status.textContent='오프라인 저장을 시작하지 못했습니다. 연결 상태를 확인해 주세요.'}));window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();promptEvent=event;if(install)install.hidden=false});install?.addEventListener('click',async()=>{if(!promptEvent)return;promptEvent.prompt();await promptEvent.userChoice;promptEvent=null;install.hidden=true});window.addEventListener('appinstalled',()=>{if(install)install.hidden=true;if(status)status.textContent='✅ SAFEKIT을 기기에 추가했습니다. 최신 경보는 계속 공식 채널에서 확인하세요.'})})();
